script:
let open_button = root_element.querySelector(".btn-open-bay");

open_button.addEventListener("click", () => {
	let dialog = new frappe.ui.Dialog({
		title: "Open Warehouse Bay",
		fields: [
			{
				fieldname: "location_name",
				fieldtype: "Data",
				label: "Warehouse Location",
				reqd: 1,
			},
		],
		primary_action_label: "Open",
		primary_action(values) {
			dialog.hide();
			go_to_warehouse_location(values.location_name.trim());
		},
	});

	dialog.show();

	// Enter key reuses the primary button's own click handler, so validation
	// and the primary_action callback stay in sync with clicking "Open".
	dialog.fields_dict.location_name.$input.on("keydown", (event) => {
		if (event.key === "Enter") {
			event.preventDefault();
			dialog.get_primary_btn().trigger("click");
		}
	});
});

function go_to_warehouse_location(location_name) {
	frappe.db.exists("Warehouse Location", location_name).then((exists) => {
		if (exists) {
			frappe.set_route("Form", "Warehouse Location", location_name);
		} else {
			frappe.route_options = {
				location_name: ["like", `%${location_name}%`],
			};
			frappe.set_route("List", "Warehouse Location", "List");
		}
	});
}

