script:
let print_swap_accessible = root_element.querySelector('.print-swap-accessible');
const slot = 'swap_tag';
const PRINTER_SETTINGS_DOCTYPE = 'Label Printer';
const PRODUCT_DOCTYPE = 'Ascend Product';
const SWAP_PRICE_DOCTYPE = 'Product Price'

let recommended_media;
let default_printer;
let selected_printer_info = null;

(async () => {
	const [media, saved_printers] = await Promise.all([
		frappe.call({ method: 'bullwheel.label_printing.get_recommended_print_media', args: { slot } })
			.then((response) => response.message),
		frappe.model.user_settings.get(PRINTER_SETTINGS_DOCTYPE),
	]);
	recommended_media = media;

	const last_printer = recommended_media && saved_printers[recommended_media];
	if (last_printer) {
		const printer_info = await frappe.db.get_value('Label Printer', last_printer, ['disabled', 'type'])
			.then((response) => response.message);
		if (printer_info && !printer_info.disabled && printer_info.type === recommended_media) {
			default_printer = last_printer;
			selected_printer_info = printer_info;
		}
	}
})();

print_swap_accessible.addEventListener("click", () => {
    let printer_name;

    let d = new frappe.ui.Dialog({
        title: 'Enter details',
        fields: [
            {
                label: 'Scan Barcode',
                fieldname: 'barcode',
                fieldtype: 'Data',
                options: 'Barcode',
                placeholder: __('Scan here')
            },
            {
                label: 'Label Printer',
                fieldname: 'printer',
                fieldtype: 'Link',
                options: 'Label Printer',
                reqd: 1,
				default: default_printer,
				get_query: () => ({
					filters: {
						disabled: 0,
						...(recommended_media ? { type: recommended_media } : {}),
					},
				}),
				async onchange() {
					printer_name = this.get_value();
					if (!printer_name) {
						selected_printer_info = null;
						return;
					}
					selected_printer_info = await frappe.db
						.get_value('Label Printer', printer_name, ['disabled', 'type'])
						.then((response) => response.message);

					if (selected_printer_info.disabled) {
						frappe.show_alert({
							message: __('{0} is disabled and cannot be used for printing.', [printer_name]),
							indicator: 'orange',
						});
						return;
					} else if (recommended_media && selected_printer_info.type !== recommended_media) {
						frappe.show_alert({
							message: __('{0} is a {1} printer, but this label recommends {2}.', [
								printer_name,
								selected_printer_info.type,
								recommended_media,
							]),
							indicator: 'orange',
						});
					}
					if (selected_printer_info && selected_printer_info.type) {
        				frappe.model.user_settings.save(
        					PRINTER_SETTINGS_DOCTYPE,
        					selected_printer_info.type,
        					printer_name
        				);
        			}
				},
            }
        ],
        size: 'extra-large', // small, large, extra-large
        primary_action_label: 'Done',
        primary_action() { // Primary action closes the dialog. It isn't the print trigger.
            d.hide();
        }
    });

    d.show();

    // Bind directly to the input so both typed Enter and scanner Enter trigger the same path.
    const control = d.get_field('barcode');
    control.$input.on('keydown', (event) => {
        if (event.key !== 'Enter') return;
        event.preventDefault();

        const scanned_value = (control.$input.val() || '').trim();
        if (!scanned_value) return;

        control.$input.val('');
        handle_scan(scanned_value, printer_name);
    });

    // Scanners act as keyboard input, so the field needs focus as soon as the dialog opens.
    control.$input.focus();
});

function handle_scan(scanned_value, printer_name) {
    const items = [{
        name: scanned_value,
        quantity: 1
    }]
    bullwheel.printing.send_print_request({
		method: 'bullwheel.label_printing.print_labels',
		printer_name: printer_name,
		slot: slot,
		doctype: PRODUCT_DOCTYPE,
		items: JSON.stringify(items),
		label: 'Swap Tag',
	});
}

style:
.swap-card {
	/*border: 1px solid var(--border-color);
	border-radius: var(--border-radius-md);
	*/
	padding: 12px;
}

.swap-card-title {
	font-weight: 600;
	margin-bottom: 8px;
}

.swap-card-actions {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 8px;
}

.swap-card-actions-big {
  display: flex;
  justify-content: flex-start;
  padding: 0px;
}

.print-swap-accessible {
  width: 100%;
  max-width: 200px;
  height: 40px;
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.2;
  color: #ffffff;
  background-color: #1a56db;
  border: 4px solid transparent;
  border-radius: 16px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.print-swap-accessible:hover {
  background-color: #133e9e;
}

.print-swap-accessible:active {
  transform: scale(0.98);
}

/* Strong visible focus ring for keyboard/low-vision navigation */
.print-swap-accessible:focus-visible {
  outline: none;
  border-color: #ffbf00;
  box-shadow: 0 0 0 4px rgba(255, 191, 0, 0.6);
}
